    "sayNone": "சுதந்திர மொழிபெயர்ப்புக்கு சாதனத்திலேயே மொழிபெயர்ப்பி உள்ள உலாவி (சமீபத்திய Chrome) தேவை. சொற்றொடர் பட்டியலின் நெருங்கிய வாக்கியங்கள் இதோ.",
