    "sayFail": "சாதன மொழிபெயர்ப்பி இந்த மொழி ஜோடிக்கு வேலை செய்யவில்லை. சொற்றொடர் பட்டியலின் நெருங்கிய வாக்கியங்கள் இதோ.",
