    "cTalk": "உண்மையான உரையாடல்களைப் பயிற்சி செய்யுங்கள்: உணவகம், வழி கேட்பது, ஷாப்பிங், மருத்துவர், ஹோட்டல். ஒரு வரியைக் கேட்டு உங்கள் பதிலைத் தேர்ந்தெடுங்கள்.",
